extraMenu.forEach(([id,name,category,price,description])=>products.push({id,name,category,price,description,compact:true,images:[],includes:[],serves:'Mais opções do Sexta'}));
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const money = n => n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const escapeHtml = v => String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean = value => String(value||'').slice(0,500);
const read = (key,fallback) => {try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}};
const persist = (key,value) => {try{localStorage.setItem(key,JSON.stringify(value));}catch{}};
let city = stores.find(s=>s.id===read('sexta-city',null))||null;
let savedBag=read('sexta-bag',[]);
let bag = Array.isArray(savedBag)?savedBag.filter(x=>x&&products.some(p=>p.id===x.id)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20).slice(0,50).map(x=>({id:x.id,qty:x.qty,notes:clean(x.notes)})):[];
let category='todos', selectedProduct=null, qty=1, pendingAction=null;
const getProduct = id => products.find(p=>p.id===id);
const priceLabel = p => p.price===null?'Sob consulta':money(p.price);
function openDialog(el){el.showModal();document.body.classList.add('modal-open');}
function closeDialog(el){el.close();if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function requireCity(action){if(city){action();return;}pendingAction=action;openDialog($('#city-dialog'));}
function setCity(id){city=stores.find(s=>s.id===id);persist('sexta-city',city.id);updateCity();closeDialog($('#city-dialog'));if(pendingAction){let action=pendingAction;pendingAction=null;action();}else toast(`Seu Sexta agora é ${city.name}.`);}
function updateCity(){const label=city?.name||'Escolha sua cidade';$('#city-label').textContent=label;$('#bag-city-label').textContent=label;renderBag();}
function whatsAppLink(phone,message){return `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;}
function openWhatsApp(phone,message){window.open(whatsAppLink(phone,message),'_blank','noopener,noreferrer');}
function productGraphic(p){if(p.category!=='bebidas')return `<div class="graphic-food" aria-label="Ilustração do Sexta"><span class="food-star">✳</span><span class="drink-type">${p.category==='burgers'?'NA<br>CHAPA.':'PRA<br>DIVIDIR.'}</span></div>`;return `<div class="graphic-drink ${p.id==='agua'?'small':''}" aria-label="Ilustração de bebida"><span class="bottle"></span><span class="drink-type">${p.id==='agua'?'PRA<br>REFRESCAR.':'BEM<br>GELADO.'}</span></div>`;}
function renderProducts(){const query=$('#search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();const visible=products.filter(p=>p.category!=='combos'&&(category==='todos'||p.category===category)&&`${p.name} ${p.description}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query));const main=visible.filter(p=>!p.compact),extra=visible.filter(p=>p.compact);$('#product-grid').innerHTML=main.map(p=>`<button class="product-card" data-product="${p.id}" aria-label="Ver ${p.name}"><div class="product-image">${p.images.length?`<img src="assets/${p.images[0]}.jpg" alt="${p.name}, imagem ilustrativa" width="1536" height="1024" loading="lazy"><span class="image-label">Imagem ilustrativa</span>`:productGraphic(p)}</div><div class="product-info"><h3>${p.name}</h3><p>${p.description}</p><div class="price-row"><span>${priceLabel(p)}</span><span class="add-circle" aria-hidden="true">+</span></div></div></button>`).join('');$('#extra-products').innerHTML=extra.map(p=>`<button class="extra-item" data-product="${p.id}" aria-label="Ver ${p.name}"><span class="extra-text"><strong>${p.name}</strong><small>${p.description}</small></span><span class="extra-price">${priceLabel(p)}</span><span class="add-circle" aria-hidden="true">+</span></button>`).join('');$('#more-count').textContent=`(${extra.length})`;$('#more-menu').classList.toggle('hidden',extra.length===0);if(query&&extra.length)$('#more-menu').open=true;$('#empty-search').classList.toggle('hidden',visible.length>0);}
function showProduct(id){const p=getProduct(id);if(!p)return;selectedProduct=p;qty=1;$('#product-detail').innerHTML=`<div class="detail-layout"><div class="detail-gallery">${p.images.length?`<img id="gallery-main" class="main-photo" src="assets/${p.images[0]}.jpg" alt="${p.name}, fotografia ilustrativa"><div class="thumbs" role="group" aria-label="Ângulos do produto">${p.images.map((im,i)=>`<button data-angle="${i}" class="${i===0?'active':''}" aria-pressed="${i===0}" aria-label="${p.angles?.[i]||'Foto do produto'}"><img src="assets/${im}.jpg" alt="${p.angles?.[i]||'Foto do produto'}"></button>`).join('')}</div><p id="angle-caption">${p.angles?.[0]||'Foto do produto'} · Fotografia ilustrativa criada com IA.</p>`:`${productGraphic(p)}<p>${p.category==='bebidas'?'Ilustração. Marca e embalagem variam conforme disponibilidade.':'Ilustração. Confira a apresentação do produto com a unidade.'}</p>`}</div><div class="detail-content"><div class="eyebrow">${p.serves}</div><h2 id="product-title">${p.name}</h2><p class="description">${p.description}</p><ul class="includes">${p.includes.map(x=>`<li>${x}</li>`).join('')}</ul><strong>${p.from?'A partir de ':''}${priceLabel(p)}</strong><label class="field-label" for="product-notes">Do seu jeito <small>· opcional</small></label><textarea id="product-notes" maxlength="500" placeholder="${p.category==='combos'||p.id==='pizza'?'Quais sabores de pizza você gostaria? Confirme as opções com a loja.':'Alguma preferência? Conte pra gente.'}"></textarea><div class="detail-footer"><div class="quantity"><button id="qty-down" aria-label="Diminuir quantidade">−</button><output id="qty-value" aria-live="polite">1</output><button id="qty-up" aria-label="Aumentar quantidade">+</button></div><button class="btn yellow" id="add-to-bag">Adicionar <span id="detail-price">${priceLabel(p)}</span></button></div><p class="fine-print">Lista de intenção de pedido. Valor final, ingredientes, disponibilidade e entrega são confirmados pela unidade.</p></div></div>`;openDialog($('#product-dialog'));}
function changeQty(delta){qty=Math.max(1,Math.min(20,qty+delta));$('#qty-value').textContent=qty;$('#detail-price').textContent=selectedProduct.price===null?'Sob consulta':money(selectedProduct.price*qty);$('#qty-down').disabled=qty===1;$('#qty-up').disabled=qty===20;}
function addToBag(){const notes=clean($('#product-notes').value.trim());const existing=bag.find(x=>x.id===selectedProduct.id&&x.notes===notes);if(existing)existing.qty=Math.min(20,existing.qty+qty);else if(bag.length<50)bag.push({id:selectedProduct.id,qty,notes});else{toast('Sua lista está cheia. Revise os itens antes de continuar.');return;}saveBag();closeDialog($('#product-dialog'));toast(`${selectedProduct.name} adicionado. Bom demais!`);}
function saveBag(){persist('sexta-bag',bag);renderBag();}
function renderBag(){const count=bag.reduce((s,x)=>s+x.qty,0),subtotal=bag.reduce((s,x)=>s+(getProduct(x.id).price||0)*x.qty,0),hasUnknown=bag.some(x=>getProduct(x.id).price===null);$('#bag-count').textContent=count;$('#mobile-count').textContent=count;$('#mobile-total').textContent=hasUnknown?'Valores a confirmar':money(subtotal);$('#mobile-bag').classList.toggle('hidden',count===0);$('#bag-items').innerHTML=bag.length?bag.map((item,i)=>{const p=getProduct(item.id);return `<div class="bag-item">${p.images.length?`<img src="assets/${p.images[0]}.jpg" alt="${p.name}">`:''}<div class="bag-item-main"><strong>${p.name}</strong>${item.notes?`<p>${escapeHtml(item.notes)}</p>`:''}<div class="bag-item-actions"><button data-bag-delta="-1" data-index="${i}" aria-label="Diminuir ${p.name}">−</button><span>${item.qty}</span><button data-bag-delta="1" data-index="${i}" aria-label="Aumentar ${p.name}">+</button><button class="remove-item" data-remove="${i}">Remover</button></div></div><span class="bag-item-price">${p.price===null?'A confirmar':money(p.price*item.qty)}</span></div>`;}).join(''):'<div class="empty-bag">Sua lista está esperando coisa boa.<br>Explore os combos e escolha seu favorito.</div>';
$('#bag-summary').innerHTML=bag.length?`<div class="summary-row"><span>${hasUnknown?'Itens com preço informado':'Subtotal estimado'}</span><span>${money(subtotal)}</span></div><p class="summary-notice">${hasUnknown?'Há itens com valor sob consulta. ':''}Entrega e possíveis adicionais não incluídos. A loja confirma os valores e a disponibilidade. Sua lista ainda não é um pedido confirmado.</p><button id="checkout" class="btn yellow checkout">Continuar no WhatsApp <span>↗</span></button><p class="summary-notice" style="margin-top:12px;margin-bottom:0">Você poderá revisar a mensagem antes de enviar.</p>${city?.order?`<a class="bag-secondary" href="${city.order}" target="_blank" rel="noopener noreferrer">Ou começar um pedido no Brendi ↗</a><p class="summary-notice">Os itens desta lista não são transferidos automaticamente para o Brendi.</p>`:''}`:'<button class="btn yellow" id="back-to-menu">Explorar o cardápio →</button>';}
function checkout(){requireCity(()=>{const lines=bag.map(x=>{const p=getProduct(x.id);return `${x.qty}x ${p.name} — ${p.price===null?'valor a confirmar':money(p.price*x.qty)}${x.notes?'\nObservações: '+x.notes:''}`;});const sum=bag.reduce((s,x)=>s+(getProduct(x.id).price||0)*x.qty,0);openWhatsApp(city.phone,`Olá, Sexta ${city.name}! Gostaria de consultar este pedido:\n\n${lines.join('\n\n')}\n\nSoma dos itens com preço informado: ${money(sum)} (entrega e adicionais não incluídos).\nPodem confirmar disponibilidade, sabores, valor final, prazo e formas de pagamento?`);});}
function showFranchise(){ $('#info-content').innerHTML=`<div class="eyebrow">EXPANSÃO SEXTA</div><h2 id="info-title">Sua cidade.<br>Um novo <em>Sexta.</em></h2><p>Vamos conversar sobre o Sexta Delivery ou Sexta Beer Pub. Deixe uma apresentação para iniciar o contato com a marca.</p><form class="franchise-form" id="franchise-form"><label>Seu nome<input name="name" required maxlength="80" autocomplete="name" placeholder="Como podemos te chamar?"></label><label>Cidade de interesse<input name="city" required maxlength="100" placeholder="Cidade e estado"></label><label>Qual formato te interessa?<select name="format"><option>Sexta Delivery</option><option>Sexta Beer Pub</option><option>Quero conhecer os dois</option></select></label><label class="consent"><input name="consent" type="checkbox" required>Quero abrir esses dados no WhatsApp de contato da marca para conversar sobre expansão.</label><button class="btn yellow" type="submit">Preparar conversa no WhatsApp <span>↗</span></button><p>Você revisa a mensagem antes de enviar. Este formulário não reserva território nem representa uma oferta formal de franquia.</p></form>`;openDialog($('#info-dialog'));}
function showPrivacy(){$('#info-content').innerHTML='<h2 id="info-title">Sua <em>privacidade.</em></h2><p>Este conceito de site guarda apenas a cidade escolhida e a lista de produtos no armazenamento local do seu navegador, para você continuar de onde parou. Não há conta de usuário nem pagamento neste site.</p><p>Ao abrir o WhatsApp, o nome dos produtos, quantidades e observações compõem uma mensagem para a unidade selecionada. No contato de expansão, são incluídos os campos que você preencher. Você precisa enviar a mensagem no WhatsApp para iniciar o atendimento.</p><p>Links externos, incluindo WhatsApp, Instagram e Brendi, têm suas próprias políticas. As fontes tipográficas são carregadas pelo Google Fonts.</p><button id="clear-local" class="btn outline">Limpar preferências deste dispositivo</button>';openDialog($('#info-dialog'));}
$('#city-options').innerHTML=stores.map(s=>`<button class="city-option" data-select-city="${s.id}"><div><strong>${s.name}</strong><small>${s.state} · ${s.label}</small></div><span>↗</span></button>`).join('');
$('#store-grid').innerHTML=stores.map((s,i)=>`<article class="store-card"><small>0${i+1} / ${s.state.toUpperCase()}</small><h3>${s.name}</h3><p>${s.address}</p><button data-store-order="${s.id}">Pedir nesta unidade <span>↗</span></button><a href="https://www.instagram.com/${s.instagram}/" target="_blank" rel="noopener noreferrer">@${s.instagram} ↗</a></article>`).join('');
document.addEventListener('click',event=>{const t=event.target.closest('button');if(!t)return;if(t.hasAttribute('data-close'))closeDialog(t.closest('dialog'));else if(t.hasAttribute('data-city-open')){pendingAction=null;openDialog($('#city-dialog'));}else if(t.dataset.selectCity)setCity(t.dataset.selectCity);else if(t.dataset.product)showProduct(t.dataset.product);else if(t.dataset.category){category=t.dataset.category;$$('[data-category]').forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',b===t);});renderProducts();}else if(t.dataset.angle!==undefined){const i=Number(t.dataset.angle);$('#gallery-main').src=`assets/${selectedProduct.images[i]}.jpg`;$('#gallery-main').alt=`${selectedProduct.name}, ${selectedProduct.angles?.[i]||'fotografia ilustrativa'}`;$('#angle-caption').textContent=`${selectedProduct.angles?.[i]||'Foto do produto'} · Fotografia ilustrativa criada com IA.`;$$('[data-angle]').forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',b===t);});}else if(t.dataset.storeOrder){city=stores.find(s=>s.id===t.dataset.storeOrder);persist('sexta-city',city.id);updateCity();$('#combos').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});toast(`Escolha seu pedido para ${city.name}.`);}else if(t.dataset.bagDelta){const i=Number(t.dataset.index);bag[i].qty+=Number(t.dataset.bagDelta);if(bag[i].qty<1)bag.splice(i,1);else bag[i].qty=Math.min(20,bag[i].qty);saveBag();}else if(t.dataset.remove!==undefined){bag.splice(Number(t.dataset.remove),1);saveBag();}else switch(t.id){case'bag-open':case'mobile-bag':openDialog($('#bag-dialog'));break;case'explore-first':pendingAction=null;closeDialog($('#city-dialog'));break;case'qty-down':changeQty(-1);break;case'qty-up':changeQty(1);break;case'add-to-bag':addToBag();break;case'checkout':checkout();break;case'back-to-menu':closeDialog($('#bag-dialog'));$('#cardapio').scrollIntoView();break;case'contact-store':requireCity(()=>openWhatsApp(city.phone,`Olá, Sexta ${city.name}! Quero consultar o cardápio e as condições de entrega.`));break;case'franchise-open':showFranchise();break;case'privacy-open':showPrivacy();break;case'clear-local':try{localStorage.removeItem('sexta-city');localStorage.removeItem('sexta-bag');}catch{}city=null;bag=[];updateCity();toast('Preferências e lista removidas deste dispositivo.');break;}});
document.addEventListener('submit',event=>{if(event.target.id!=='franchise-form')return;event.preventDefault();const form=new FormData(event.target);openWhatsApp(stores[0].phone,`Olá! Meu nome é ${form.get('name')}. Tenho interesse na expansão do ${form.get('format')} em ${form.get('city')}. Gostaria de conhecer a proposta e falar com o responsável pela expansão.`);});
$('#search').addEventListener('input',renderProducts);
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');if(d.id==='city-dialog')pendingAction=null;});d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d);});});
renderProducts();updateCity();
if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){document.documentElement.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el));}
if(!city)openDialog($('#city-dialog'));
